with src as (
  select v.chapter_id, v.level_id, v.atom_key, v.atom_type, v.atom_order, v.title, v.body::jsonb as body
  from (values
    -- ═══ CLASS 6-8 PHYSICS (872-881) ═══
    (872, 'class_6_8', 'force-68-concept', 'concept', 1, 'बल — Class 6-8',
     $j${"text":"बल एक धक्का या खिंचाव है। जब तुम गेंद को किक मारते हो — वो बल है। जब तुम दरवाज़ा खींचते हो — वो भी बल है। बल से चीज़ें तेज़ चलती हैं, रुकती हैं, या अपना आकार बदलती हैं। दो तरह के बल: contact (छूकर लगाना) और non-contact (चुंबक, गुरुत्व)।","note":"बल = धक्का या खिंचाव · न्यूटन (N) में नापते हैं"}$j$),
    (872, 'class_6_8', 'force-68-formula', 'formula', 2, 'बल — सरल बात',
     $j${"formula":"बल = कुछ भारी हो तो ज़्यादा लगेगा, हल्का हो तो कम","explanation":"भारी पत्थर उठाने में ज़्यादा बल, पेन उठाने में कम"}$j$),
    (872, 'class_6_8', 'force-68-example', 'example', 3, 'सरल उदाहरण',
     $j${"question":"गेंद को किक मारना कौन सा बल?","solution":"पैर से गेंद को धक्का (contact force)","answer":"Contact force (धक्का)"}$j$),
    (872, 'class_6_8', 'force-68-mcq', 'mcq', 4, 'Class 6-8 MCQs',
     $j${"questions":[{"q":"बल क्या है?","options":["धक्का या खिंचाव","सिर्फ धक्का","सिर्फ खिंचाव","कोई नहीं"],"answer":0,"explanation":"धक्का या खिंचाव = बल"},{"q":"चुंबक द्वारा लोहे को खींचना कौन सा बल?","options":["Contact","Non-contact","दोनों","कोई नहीं"],"answer":1,"explanation":"चुंबक बिना छुए खींचता है"}]}$j$),

    (873, 'class_6_8', 'work-68-concept', 'concept', 1, 'कार्य-ऊर्जा — Class 6-8',
     $j${"text":"जब किसी चीज़ पर बल लगाकर उसे हिलाया जाता है, तो कहते हैं कार्य (Work) हुआ। जैसे पत्थर उठाना, गेंद को दूर फेंकना। ऊर्जा (Energy) वो चीज़ है जो काम करने की ताकत देती है। खाना खाने से हमें ऊर्जा मिलती है, तभी हम खेल पाते हैं।","note":"कार्य = बल + हिलना · ऊर्जा = काम करने की ताकत"}$j$),
    (873, 'class_6_8', 'work-68-formula', 'formula', 2, 'कार्य — सरल बात',
     $j${"formula":"कार्य = बल × दूरी (जितनी दूर हिलाया)","explanation":"भारी चीज़ को ज़्यादा दूर ले जाओ → ज़्यादा कार्य"}$j$),
    (873, 'class_6_8', 'work-68-example', 'example', 3, 'सरल उदाहरण',
     $j${"question":"किताब उठाना कार्य है या नहीं?","solution":"हाँ — बल लगाया + ऊपर उठाया (दूरी)","answer":"हाँ, कार्य है"}$j$),
    (873, 'class_6_8', 'work-68-mcq', 'mcq', 4, 'Class 6-8 MCQs',
     $j${"questions":[{"q":"कार्य कब होता है?","options":["सिर्फ बल लगाओ","बल + हिलना","सिर्फ देखना","सोचना"],"answer":1,"explanation":"बल + दूरी = कार्य"},{"q":"ऊर्जा कहाँ से?","options":["हवा","खाना","पानी","सोच"],"answer":1,"explanation":"खाने से ऊर्जा मिलती है"}]}$j$),

    (874, 'class_6_8', 'grav-68-concept', 'concept', 1, 'गुरुत्वाकर्षण — Class 6-8',
     $j${"text":"पृथ्वी हर चीज़ को अपनी तरफ खींचती है — इसे गुरुत्वाकर्षण (Gravity) कहते हैं। इसीलिए गेंद ऊपर फेंको तो नीचे आती है। चंद्रमा पृथ्वी के चारों ओर घूमता है क्योंकि पृथ्वी उसे खींचती है। बिना गुरुत्व के हम हवा में उड़ते रहते।","note":"गुरुत्व = पृथ्वी का खिंचाव · चीज़ें नीचे गिरती हैं"}$j$),
    (874, 'class_6_8', 'grav-68-formula', 'formula', 2, 'गुरुत्व — सरल बात',
     $j${"formula":"भारी चीज़ = ज़्यादा खिंचाव · हल्की चीज़ = कम खिंचाव","explanation":"पृथ्वी सबको नीचे खींचती है — बड़े या छोटे, सबको"}$j$),
    (874, 'class_6_8', 'grav-68-example', 'example', 3, 'सरल उदाहरण',
     $j${"question":"गेंद ऊपर फेंको तो नीचे क्यों आती है?","solution":"पृथ्वी उसे नीचे खींचती है","answer":"गुरुत्वाकर्षण (gravity)"}$j$),
    (874, 'class_6_8', 'grav-68-mcq', 'mcq', 4, 'Class 6-8 MCQs',
     $j${"questions":[{"q":"चीज़ें नीचे क्यों गिरती हैं?","options":["हवा","गुरुत्व","चुंबक","बिजली"],"answer":1,"explanation":"गुरुत्व (gravity)"},{"q":"चंद्रमा पृथ्वी के चारों ओर क्यों घूमता है?","options":["हवा","रस्सी","गुरुत्व","कोई नहीं"],"answer":2,"explanation":"पृथ्वी का गुरुत्व खींचता है"}]}$j$),

    (875, 'class_6_8', 'press-68-concept', 'concept', 1, 'दाब — Class 6-8',
     $j${"text":"दाब (Pressure) = कितना बल कितने क्षेत्रफल पर। पतला नुकीला पेन आसानी से लिखता है क्योंकि कम जगह पर ज़्यादा बल। मोटी चप्पल पहनो तो चलना आसान, पतली सुई पर चलो तो दर्द — दोनों में बल वही, पर क्षेत्रफल अलग। पानी में गहरे जाओ तो दाब ज़्यादा।","note":"दाब = बल / क्षेत्रफल · जितना पतला, उतना ज़्यादा दाब"}$j$),
    (875, 'class_6_8', 'press-68-formula', 'formula', 2, 'दाब — सरल बात',
     $j${"formula":"दाब = बल / क्षेत्रफल (F/A)","explanation":"कम क्षेत्रफल → ज़्यादा दाब (नुकीली सुई)"}$j$),
    (875, 'class_6_8', 'press-68-example', 'example', 3, 'सरल उदाहरण',
     $j${"question":"सुई से आसानी से कपड़ा क्यों छिदता है?","solution":"सुई पतली → कम क्षेत्रफल → ज़्यादा दाब","answer":"ज़्यादा दाब (कम क्षेत्रफल)"}$j$),
    (875, 'class_6_8', 'press-68-mcq', 'mcq', 4, 'Class 6-8 MCQs',
     $j${"questions":[{"q":"दाब = ?","options":["बल × क्षेत्रफल","बल / क्षेत्रफल","क्षेत्रफल / बल","बल + क्षेत्रफल"],"answer":1,"explanation":"F/A"},{"q":"नुकीली सुई क्यों?","options":["ज़्यादा बल","कम क्षेत्रफल","ज़्यादा दाब","दोनों 2 और 3"],"answer":3,"explanation":"कम क्षेत्रफल = ज़्यादा दाब"}]}$j$),

    (876, 'class_6_8', 'heat-68-concept', 'concept', 1, 'ऊष्मा — Class 6-8',
     $j${"text":"ऊष्मा (Heat) गर्मी है। गर्म चीज़ों से ठंडी चीज़ों में गर्मी जाती है। जब हम चाय में गर्म पानी डालते हैं, चम्मच गर्म हो जाता है। थर्मामीटर से तापमान नापते हैं। बुखार में शरीर का तापमान बढ़ जाता है।","note":"गर्मी = ऊष्मा · तापमान = कितना गर्म/ठंडा"}$j$),
    (876, 'class_6_8', 'heat-68-formula', 'formula', 2, 'ऊष्मा — सरल बात',
     $j${"formula":"गर्मी जाती है गर्म से ठंडे की तरफ","explanation":"तापमान डिग्री सेल्सियस (°C) में"}$j$),
    (876, 'class_6_8', 'heat-68-example', 'example', 3, 'सरल उदाहरण',
     $j${"question":"बुखार में तापमान क्यों बढ़ता है?","solution":"शरीर ज़्यादा गर्म हो जाता है","answer":"तापमान बढ़ता है (fever)"}$j$),
    (876, 'class_6_8', 'heat-68-mcq', 'mcq', 4, 'Class 6-8 MCQs',
     $j${"questions":[{"q":"तापमान किससे नापते हैं?","options":["रूलर","थर्मामीटर","तराज़ू","घड़ी"],"answer":1,"explanation":"थर्मामीटर"},{"q":"गर्मी किस तरफ जाती है?","options":["ठंडे→गर्म","गर्म→ठंडे","कोई नहीं","दोनों"],"answer":1,"explanation":"गर्म से ठंडे की तरफ"}]}$j$),

    (877, 'class_6_8', 'wave-68-concept', 'concept', 1, 'तरंगें — Class 6-8',
     $j${"text":"तरंग (Wave) एक जगह से दूसरी जगह ऊर्जा ले जाती है। जब तुम पानी में कंकड़ फेंकते हो, तो लहरें (ripples) बनती हैं — वो तरंगें हैं। तरंगें दो तरह की: जिनमें माध्यम चाहिए (पानी, ध्वनि) और जिनमें नहीं चाहिए (प्रकाश)।","note":"तरंग = ऊर्जा का सफर"}$j$),
    (877, 'class_6_8', 'wave-68-formula', 'formula', 2, 'तरंग — सरल बात',
     $j${"formula":"तरंग = एक जगह से दूसरी जगह ऊर्जा ले जाना","explanation":"पानी में लहर, रस्सी हिलाना, रेडियो की तरंगें"}$j$),
    (877, 'class_6_8', 'wave-68-example', 'example', 3, 'सरल उदाहरण',
     $j${"question":"पानी में लहरें क्या हैं?","solution":"पानी की तरंगें","answer":"तरंग (water waves)"}$j$),
    (877, 'class_6_8', 'wave-68-mcq', 'mcq', 4, 'Class 6-8 MCQs',
     $j${"questions":[{"q":"तरंग क्या ले जाती है?","options":["पानी","ऊर्जा","हवा","मिट्टी"],"answer":1,"explanation":"ऊर्जा"},{"q":"पानी में लहर उदाहरण?","options":["हवा","तरंग","गुरुत्व","दाब"],"answer":1,"explanation":"तरंग का उदाहरण"}]}$j$),

    (878, 'class_6_8', 'sound-68-concept', 'concept', 1, 'ध्वनि — Class 6-8',
     $j${"text":"ध्वनि (Sound) वो है जो हम कानों से सुनते हैं। बोलने पर, थाली बजाने पर, पक्षियों के चहचहाने पर ध्वनि निकलती है। ध्वनि के लिए हवा (या कोई माध्यम) चाहिए — चाँद पर कोई आवाज़ नहीं सुनाई देगी क्योंकि वहाँ हवा नहीं।","note":"ध्वनि के लिए माध्यम चाहिए (हवा, पानी)"}$j$),
    (878, 'class_6_8', 'sound-68-formula', 'formula', 2, 'ध्वनि — सरल बात',
     $j${"formula":"ध्वनि = कंपन · माध्यम चाहिए (हवा/पानी)","explanation":"चाँद पर ध्वनि नहीं — हवा नहीं है"}$j$),
    (878, 'class_6_8', 'sound-68-example', 'example', 3, 'सरल उदाहरण',
     $j${"question":"चाँद पर बात क्यों नहीं सुनाई देती?","solution":"हवा नहीं है (माध्यम नहीं)","answer":"ध्वनि को माध्यम चाहिए"}$j$),
    (878, 'class_6_8', 'sound-68-mcq', 'mcq', 4, 'Class 6-8 MCQs',
     $j${"questions":[{"q":"ध्वनि किससे सुनते हैं?","options":["आँख","कान","नाक","जीभ"],"answer":1,"explanation":"कान"},{"q":"ध्वनि को क्या चाहिए?","options":["रोशनी","माध्यम","गुरुत्व","बिजली"],"answer":1,"explanation":"माध्यम (हवा आदि)"}]}$j$),

    (879, 'class_6_8', 'light-68-concept', 'concept', 1, 'प्रकाश — Class 6-8',
     $j${"text":"प्रकाश (Light) से हम देख पाते हैं। सूरज, बल्ब, मोमबत्ती — सब प्रकाश देते हैं। प्रकाश सीधी लाइन में चलता है। शीशे में हम अपना चेहरा देखते हैं क्योंकि प्रकाश परावर्तित (reflect) होता है। पानी में डाली गई पेंसिल मुड़ी हुई दिखती है — यह अपवर्तन (refraction) है।","note":"प्रकाश सीधा चलता है · शीशा = परावर्तन · पानी = अपवर्तन"}$j$),
    (879, 'class_6_8', 'light-68-formula', 'formula', 2, 'प्रकाश — सरल बात',
     $j${"formula":"प्रकाश सीधी लाइन में चलता है","explanation":"परछाई बनती है — बीच में चीज़ आने से"}$j$),
    (879, 'class_6_8', 'light-68-example', 'example', 3, 'सरल उदाहरण',
     $j${"question":"शीशे में चेहरा क्यों दिखता है?","solution":"प्रकाश शीशे से परावर्तित होता है","answer":"परावर्तन (reflection)"}$j$),
    (879, 'class_6_8', 'light-68-mcq', 'mcq', 4, 'Class 6-8 MCQs',
     $j${"questions":[{"q":"शीशे में चेहरा किस कारण?","options":["अपवर्तन","परावर्तन","ध्वनि","गुरुत्व"],"answer":1,"explanation":"परावर्तन (reflection)"},{"q":"परछाई कब बनती है?","options":["रोशनी में","बीच में चीज़","पानी में","हवा में"],"answer":1,"explanation":"चीज़ प्रकाश रोकती है"}]}$j$),

    (880, 'class_6_8', 'elec-68-concept', 'concept', 1, 'विद्युत — Class 6-8',
     $j${"text":"बिजली (Electricity) से बल्ब जलता है, पंखा चलता है। सेल/बैटरी में बिजली होती है। जब तार से करंट बहता है, तो काम होता है। स्विच से हम बिजली चालू/बंद करते हैं। बिजली से बचके रहो — पानी में हाथ गीले हाथों से स्विच मत छुओ।","note":"बिजली = करंट (current) · तार + बैटरी + बल्ब = सर्किट"}$j$),
    (880, 'class_6_8', 'elec-68-formula', 'formula', 2, 'विद्युत — सरल बात',
     $j${"formula":"बिजली के लिए बंद सर्किट चाहिए (पूरा रास्ता)","explanation":"बंद सर्किट = बल्ब जलता है · खुला = नहीं"}$j$),
    (880, 'class_6_8', 'elec-68-example', 'example', 3, 'सरल उदाहरण',
     $j${"question":"स्विच बंद करने से बल्ब क्यों बंद होता है?","solution":"सर्किट टूट जाता है — बिजली नहीं बहती","answer":"सर्किट खुल जाता है"}$j$),
    (880, 'class_6_8', 'elec-68-mcq', 'mcq', 4, 'Class 6-8 MCQs',
     $j${"questions":[{"q":"बल्ब जलने के लिए क्या चाहिए?","options":["खुला सर्किट","बंद सर्किट","पानी","हवा"],"answer":1,"explanation":"बंद सर्किट"},{"q":"बिजली से बचाव?","options":["गीले हाथ","सूखे हाथ","पानी में","नंगे पैर"],"answer":1,"explanation":"सूखे हाथ से स्विच छुओ"}]}$j$),

    (881, 'class_6_8', 'mag-68-concept', 'concept', 1, 'चुंबकत्व — Class 6-8',
     $j${"text":"चुंबक (Magnet) लोहे की चीज़ों को अपनी तरफ खींचता है। जैसे फ्रिज पर लगी चुंबक, कम्पास की सुई। चुंबक के दो सिरे होते हैं — उत्तरी ध्रुव (N) और दक्षिणी ध्रुव (S)। दो चुंबक के एक जैसे ध्रुव एक-दूसरे को दूर भगाते हैं, अलग ध्रुव पास आते हैं।","note":"चुंबक = लोहे को खींचता है · N-N दूर, N-S पास"}$j$),
    (881, 'class_6_8', 'mag-68-formula', 'formula', 2, 'चुंबक — सरल बात',
     $j${"formula":"चुंबक लोहे/निकल/कोबाल्ट को खींचता है · N-N (दूर), N-S (पास)","explanation":"चुंबक के दो ध्रुव — N और S"}$j$),
    (881, 'class_6_8', 'mag-68-example', 'example', 3, 'सरल उदाहरण',
     $j${"question":"चुंबक किसको खींचता है?","solution":"लोहे की चीज़ें (लोहा, निकल, कोबाल्ट)","answer":"लोहा (iron)"}$j$),
    (881, 'class_6_8', 'mag-68-mcq', 'mcq', 4, 'Class 6-8 MCQs',
     $j${"questions":[{"q":"चुंबक किसको खींचता है?","options":["लकड़ी","प्लास्टिक","लोहा","कागज़"],"answer":2,"explanation":"लोहा (iron)"},{"q":"N-N ध्रुव क्या करते हैं?","options":["पास आते","दूर भागते","कोई नहीं","मिल जाते"],"answer":1,"explanation":"Same poles repel"}]}$j$),

    -- ═══ CLASS 6-8 CHEMISTRY (885-887) ═══
    (885, 'class_6_8', 'matter-68-concept', 'concept', 1, 'पदार्थ — Class 6-8',
     $j${"text":"हर चीज़ जो जगह लेती है और भार होता है, उसे पदार्थ (Matter) कहते हैं। पदार्थ तीन तरह का: ठोस (solid — पत्थर, बर्फ), तरल (liquid — पानी, दूध), गैस (gas — हवा, भाप)। ठोस का आकार तय, तरल का नहीं, गैस कहीं भी फैल जाती है।","note":"ठोस (solid), तरल (liquid), गैस (gas) — तीन अवस्थाएँ"}$j$),
    (885, 'class_6_8', 'matter-68-formula', 'formula', 2, 'पदार्थ — सरल बात',
     $j${"formula":"बर्फ (ठोस) → पानी (तरल) → भाप (गैस)","explanation":"गर्मी देने से अवस्था बदलती है"}$j$),
    (885, 'class_6_8', 'matter-68-example', 'example', 3, 'सरल उदाहरण',
     $j${"question":"बर्फ कौन सी अवस्था?","solution":"ठोस (solid)","answer":"ठोस (solid)"}$j$),
    (885, 'class_6_8', 'matter-68-mcq', 'mcq', 4, 'Class 6-8 MCQs',
     $j${"questions":[{"q":"पानी कौन सी अवस्था?","options":["ठोस","तरल","गैस","प्लाज़्मा"],"answer":1,"explanation":"तरल (liquid)"},{"q":"किसका आकार तय?","options":["ठोस","तरल","गैस","कोई नहीं"],"answer":0,"explanation":"ठोस का आकार तय"}]}$j$),

    (886, 'class_6_8', 'atom-68-concept', 'concept', 1, 'परमाणु — Class 6-8',
     $j${"text":"हर चीज़ छोटे-छोटे कणों से बनी है — इन्हें परमाणु (Atom) कहते हैं। पानी की एक बूँद में अरबों परमाणु हैं। परमाणु में तीन चीज़ें: प्रोटॉन (+ve), न्यूट्रॉन (0), इलेक्ट्रॉन (−ve)। परमाणु इतने छोटे हैं कि आँख से नहीं दिखते।","note":"परमाणु = सबसे छोटा कण · प्रोटॉन+, न्यूट्रॉन 0, इलेक्ट्रॉन−"}$j$),
    (886, 'class_6_8', 'atom-68-formula', 'formula', 2, 'परमाणु — सरल बात',
     $j${"formula":"परमाणु = प्रोटॉन + न्यूट्रॉन + इलेक्ट्रॉन","explanation":"प्रोटॉन +, न्यूट्रॉन 0, इलेक्ट्रॉन −"}$j$),
    (886, 'class_6_8', 'atom-68-example', 'example', 3, 'सरल उदाहरण',
     $j${"question":"परमाणु में क्या-क्या होता है?","solution":"प्रोटॉन, न्यूट्रॉन, इलेक्ट्रॉन","answer":"तीनों कण"}$j$),
    (886, 'class_6_8', 'atom-68-mcq', 'mcq', 4, 'Class 6-8 MCQs',
     $j${"questions":[{"q":"सबसे छोटा कण?","options":["कोशिका","परमाणु","अणु","धूल"],"answer":1,"explanation":"परमाणु (atom)"},{"q":"इलेक्ट्रॉन का charge?","options":["+","−","0","दोनों"],"answer":1,"explanation":"इलेक्ट्रॉन = negative"}]}$j$),

    (887, 'class_6_8', 'periodic-68-concept', 'concept', 1, 'आवर्त सारणी — Class 6-8',
     $j${"text":"दुनिया में 118 तरह के परमाणु (elements) हैं — जैसे ऑक्सीजन, हाइड्रोजन, लोहा, सोना। इन सबको एक तालिका में रखा गया है — उसे आवर्त सारणी (Periodic Table) कहते हैं। सबसे हल्का element हाइड्रोजन, सबसे भारी यूरेनियम (प्राकृतिक)।","note":"118 elements · हाइड्रोजन (H) सबसे हल्का"}$j$),
    (887, 'class_6_8', 'periodic-68-formula', 'formula', 2, 'आवर्त सारणी — सरल बात',
     $j${"formula":"118 तरह के elements · हर एक का नाम और symbol","explanation":"जैसे ऑक्सीजन = O, हाइड्रोजन = H, सोना = Au"}$j$),
    (887, 'class_6_8', 'periodic-68-example', 'example', 3, 'सरल उदाहरण',
     $j${"question":"पानी में कौन से elements?","solution":"H₂O = 2 हाइड्रोजन + 1 ऑक्सीजन","answer":"हाइड्रोजन + ऑक्सीजन"}$j$),
    (887, 'class_6_8', 'periodic-68-mcq', 'mcq', 4, 'Class 6-8 MCQs',
     $j${"questions":[{"q":"कुल elements?","options":["50","100","118","200"],"answer":2,"explanation":"118"},{"q":"सबसे हल्का element?","options":["ऑक्सीजन","हाइड्रोजन","लोहा","सोना"],"answer":1,"explanation":"हाइड्रोजन"}]}$j$),

    -- ═══ CLASS 6-8 BIOLOGY (901-907) ═══
    (901, 'class_6_8', 'cell-68-concept', 'concept', 1, 'कोशिका — Class 6-8',
     $j${"text":"कोशिका (Cell) जीवन की सबसे छोटी इकाई है। हमारा शरीर अरबों कोशिकाओं से बना है। कोशिका में एक छोटा-सा nucleus (दिमाग) होता है, और बाहर membrane होती है। पौधे और जानवर — दोनों की कोशिकाएँ होती हैं, पर पौधे की कोशिका में हरा रंग (chloroplast) होता है।","note":"कोशिका = जीवन की सबसे छोटी इकाई"}$j$),
    (901, 'class_6_8', 'cell-68-formula', 'formula', 2, 'कोशिका — सरल बात',
     $j${"formula":"कोशिका = nucleus + membrane + cytoplasm","explanation":"पौधे की कोशिका में chloroplast (हरा) भी"}$j$),
    (901, 'class_6_8', 'cell-68-example', 'example', 3, 'सरल उदाहरण',
     $j${"question":"कोशिका क्या है?","solution":"जीवन की सबसे छोटी इकाई","answer":"कोशिका (cell)"}$j$),
    (901, 'class_6_8', 'cell-68-mcq', 'mcq', 4, 'Class 6-8 MCQs',
     $j${"questions":[{"q":"जीवन की सबसे छोटी इकाई?","options":["परमाणु","कोशिका","अंग","धूल"],"answer":1,"explanation":"कोशिका (cell)"},{"q":"पौधे की कोशिका में हरा रंग क्या?","options":["nucleus","membrane","chloroplast","cytoplasm"],"answer":2,"explanation":"chloroplast (हरा)"}]}$j$),

    (902, 'class_6_8', 'tissue-68-concept', 'concept', 1, 'ऊतक — Class 6-8',
     $j${"text":"एक जैसी कोशिकाएँ मिलकर ऊतक (Tissue) बनाती हैं। हमारे शरीर में अलग-अलग ऊतक — मांसपेशी (muscle), हड्डी (bone), त्वचा (skin)। पौधे में पत्ती, तना, जड़ — अलग ऊतक। जब अलग ऊतक मिलते हैं, तो अंग (organ) बनते हैं — जैसे दिल, फेफड़े।","note":"कोशिका → ऊतक → अंग → शरीर"}$j$),
    (902, 'class_6_8', 'tissue-68-formula', 'formula', 2, 'ऊतक — सरल बात',
     $j${"formula":"कोशिका + कोशिका = ऊतक · ऊतक + ऊतक = अंग","explanation":"मांसपेशी, हड्डी, त्वचा — सब ऊतक"}$j$),
    (902, 'class_6_8', 'tissue-68-example', 'example', 3, 'सरल उदाहरण',
     $j${"question":"हड्डी क्या है?","solution":"ऊतक (bone tissue)","answer":"ऊतक (connective)"}$j$),
    (902, 'class_6_8', 'tissue-68-mcq', 'mcq', 4, 'Class 6-8 MCQs',
     $j${"questions":[{"q":"ऊतक किससे बनता है?","options":["परमाणु","कोशिकाएँ","अंग","धूल"],"answer":1,"explanation":"कोशिकाएँ"},{"q":"दिल क्या है?","options":["ऊतक","अंग","कोशिका","परमाणु"],"answer":1,"explanation":"अंग (organ)"}]}$j$),

    (903, 'class_6_8', 'animal-68-concept', 'concept', 1, 'जंतु — Class 6-8',
     $j${"text":"जानवर कई तरह के हैं — छोटे (कीड़े) से लेकर बड़े (हाथी)। कुछ जानवर घास खाते हैं (शाकाहारी — गाय, बकरी), कुछ मांस खाते हैं (मांसाहारी — शेर, बाघ), कुछ दोनों (सर्वाहारी — इंसान, कौआ)। जानवर हिलते-डुलते हैं, खाते हैं, बढ़ते हैं।","note":"शाकाहारी (herbivore), मांसाहारी (carnivore), सर्वाहारी (omnivore)"}$j$),
    (903, 'class_6_8', 'animal-68-formula', 'formula', 2, 'जंतु — सरल बात',
     $j${"formula":"शाकाहारी (घास) · मांसाहारी (मांस) · सर्वाहारी (दोनों)","explanation":"गाय = शाकाहारी, शेर = मांसाहारी, इंसान = सर्वाहारी"}$j$),
    (903, 'class_6_8', 'animal-68-example', 'example', 3, 'सरल उदाहरण',
     $j${"question":"शेर किस तरह का जानवर?","solution":"मांस खाता है","answer":"मांसाहारी (carnivore)"}$j$),
    (903, 'class_6_8', 'animal-68-mcq', 'mcq', 4, 'Class 6-8 MCQs',
     $j${"questions":[{"q":"गाय किस तरह?","options":["मांसाहारी","शाकाहारी","सर्वाहारी","कोई नहीं"],"answer":1,"explanation":"शाकाहारी (grass)"},{"q":"इंसान कौन सा?","options":["मांसाहारी","शाकाहारी","सर्वाहारी","कोई नहीं"],"answer":2,"explanation":"दोनों खाता है (सर्वाहारी)"}]}$j$),

    (904, 'class_6_8', 'plant-68-concept', 'concept', 1, 'पौधे — Class 6-8',
     $j${"text":"पौधे अपना खाना खुद बनाते हैं (प्रकाश संश्लेषण)। पौधे के तीन मुख्य भाग: जड़ (root — पानी सोखती), तना (stem — सहारा देता), पत्ती (leaf — खाना बनाती)। फूल और फल पौधे के प्रजनन के लिए। कुछ पौधे बहुत बड़े (पीपल) तो कुछ छोटे (तुलसी)।","note":"जड़, तना, पत्ती, फूल, फल — पौधे के भाग"}$j$),
    (904, 'class_6_8', 'plant-68-formula', 'formula', 2, 'पौधे — सरल बात',
     $j${"formula":"जड़ → पानी सोखती · तना → सहारा · पत्ती → खाना बनाती","explanation":"पौधे का खाना = प्रकाश संश्लेषण"}$j$),
    (904, 'class_6_8', 'plant-68-example', 'example', 3, 'सरल उदाहरण',
     $j${"question":"पौधे खाना कैसे बनाते हैं?","solution":"पत्ती में सूरज की रोशनी + पानी + हवा से","answer":"प्रकाश संश्लेषण (photosynthesis)"}$j$),
    (904, 'class_6_8', 'plant-68-mcq', 'mcq', 4, 'Class 6-8 MCQs',
     $j${"questions":[{"q":"पानी कहाँ से सोखा जाता है?","options":["तना","जड़","पत्ती","फूल"],"answer":1,"explanation":"जड़ (root)"},{"q":"खाना कहाँ बनता है?","options":["जड़","तना","पत्ती","फूल"],"answer":2,"explanation":"पत्ती (leaf)"}]}$j$),

    (905, 'class_6_8', 'nutrition-68-concept', 'concept', 1, 'पोषण — Class 6-8',
     $j${"text":"हमें ज़िंदा रहने और बढ़ने के लिए खाना चाहिए। खाने से हमें एनर्जी मिलती है। अलग-अलग तरह के खाने: अनाज (रोटी, चावल — एनर्जी), दाल-सब्ज़ी (प्रोटीन — मांसपेशी), फल-दूध (विटामिन — स्वस्थ), तेल-घी (फैट — एनर्जी)। संतुलित खाना खाओ।","note":"अनाज, दाल, सब्ज़ी, फल, दूध — सब ज़रूरी"}$j$),
    (905, 'class_6_8', 'nutrition-68-formula', 'formula', 2, 'पोषण — सरल बात',
     $j${"formula":"संतुलित खाना = अनाज + दाल + सब्ज़ी + फल + दूध","explanation":"हर तरह का खाना ज़रूरी"}$j$),
    (905, 'class_6_8', 'nutrition-68-example', 'example', 3, 'सरल उदाहरण',
     $j${"question":"रोटी से क्या मिलता है?","solution":"एनर्जी (कार्बोहाइड्रेट)","answer":"एनर्जी (carbohydrates)"}$j$),
    (905, 'class_6_8', 'nutrition-68-mcq', 'mcq', 4, 'Class 6-8 MCQs',
     $j${"questions":[{"q":"दाल से क्या मिलता है?","options":["फैट","प्रोटीन","विटामिन","पानी"],"answer":1,"explanation":"प्रोटीन"},{"q":"फल से क्या?","options":["एनर्जी","प्रोटीन","विटामिन","फैट"],"answer":2,"explanation":"विटामिन"}]}$j$),

    (906, 'class_6_8', 'photo-68-concept', 'concept', 1, 'प्रकाश संश्लेषण — Class 6-8',
     $j${"text":"पौधे अपना खाना खुद बनाते हैं — इसे प्रकाश संश्लेषण (Photosynthesis) कहते हैं। इसके लिए चाहिए: सूरज की रोशनी, पानी, और हवा से CO₂। पत्ती में हरा पदार्थ (chlorophyll) होता है जो सूरज की रोशनी पकड़ता है। पौधे हमें ऑक्सीजन भी देते हैं।","note":"प्रकाश संश्लेषण = सूरज + पानी + CO₂ → खाना + O₂"}$j$),
    (906, 'class_6_8', 'photo-68-formula', 'formula', 2, 'प्रकाश संश्लेषण — सरल बात',
     $j${"formula":"सूरज की रोशनी + पानी + CO₂ → खाना + O₂","explanation":"पौधे दिन में खाना बनाते हैं (सूरज की रोशनी में)"}$j$),
    (906, 'class_6_8', 'photo-68-example', 'example', 3, 'सरल उदाहरण',
     $j${"question":"पौधे दिन में क्या बनाते हैं?","solution":"खाना (glucose) और O₂","answer":"खाना + ऑक्सीजन"}$j$),
    (906, 'class_6_8', 'photo-68-mcq', 'mcq', 4, 'Class 6-8 MCQs',
     $j${"questions":[{"q":"प्रकाश संश्लेषण कब होता है?","options":["रात में","दिन में (सूरज)","बारिश में","हमेशा"],"answer":1,"explanation":"सूरज की रोशनी में"},{"q":"पौधे हमें क्या देते हैं?","options":["CO₂","O₂","पानी","मिट्टी"],"answer":1,"explanation":"ऑक्सीजन (O₂)"}]}$j$),

    (907, 'class_6_8', 'digest-68-concept', 'concept', 1, 'पाचन — Class 6-8',
     $j${"text":"हम जो खाना खाते हैं, वो सीधे शरीर में नहीं जाता। पहले पेट में पचता है — छोटे टुकड़ों में टूटता है। पाचन (Digestion) मुँह से शुरू होता है (दाँत + लार), फिर पेट, फिर छोटी आंत। छोटी आंत से पोषण शरीर में जाता है।","note":"मुँह → पेट → छोटी आंत → बड़ी आंत"}$j$),
    (907, 'class_6_8', 'digest-68-formula', 'formula', 2, 'पाचन — सरल बात',
     $j${"formula":"खाना → छोटे टुकड़े → पोषण शरीर में","explanation":"पाचन मुँह से शुरू होता है"}$j$),
    (907, 'class_6_8', 'digest-68-example', 'example', 3, 'सरल उदाहरण',
     $j${"question":"पाचन कहाँ शुरू होता है?","solution":"मुँह में (दाँत + लार)","answer":"मुँह (mouth)"}$j$),
    (907, 'class_6_8', 'digest-68-mcq', 'mcq', 4, 'Class 6-8 MCQs',
     $j${"questions":[{"q":"पाचन कहाँ शुरू?","options":["पेट","मुँह","आंत","गला"],"answer":1,"explanation":"मुँह"},{"q":"पोषण कहाँ से शरीर में?","options":["पेट","छोटी आंत","बड़ी आंत","मुँह"],"answer":1,"explanation":"छोटी आंत (small intestine)"}]}$j$)
  ) as v(chapter_id, level_id, atom_key, atom_type, atom_order, title, body)
)
insert into mtb.atoms (chapter_id, level_id, atom_key, atom_type, atom_order, title, body, lang, status, archived, exam_tags, class_tags, subject_tag, difficulty, content_hash)
select s.chapter_id, s.level_id, s.atom_key, s.atom_type, s.atom_order, s.title, s.body, 'hi', 'published', false,
  '{}'::text[], array['class_6','class_7','class_8']::text[],
  'general-science', 'easy', md5(s.body::text)
from src s
on conflict do nothing;

